// SERVED MODEL: claude-opus-5-5
// X-W12U Repair 1 (C7-1): attribute the eager JS set of a built dist/gh-pages
// to its source owners, via the hidden sourcemaps (`vite build --mode gh-pages
// --sourcemap hidden`). Same eager-set definition as scripts/perf/eager-bytes.mjs
// (module entry + every modulepreload, <noscript> stripped). Raw generated bytes
// are attributed per source segment; gz per chunk is distributed pro rata.
// Usage: node eager-attrib.mjs <dist/gh-pages dir> [--json]
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { gzipSync } from "node:zlib";
const dist = process.argv[2];
const html = readFileSync(join(dist, "index.html"), "utf8").replace(/<noscript>[\s\S]*?<\/noscript>/g, "");
const hrefs = new Set();
for (const m of html.matchAll(/<script[^>]*type="module"[^>]*src="([^"]+)"/g)) hrefs.add(m[1]);
for (const m of html.matchAll(/<link[^>]*rel="modulepreload"[^>]*href="([^"]+)"/g)) hrefs.add(m[1]);
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const dec = (s) => { const out = []; let v = 0, sh = 0; for (const c of s) { const d = B64.indexOf(c); v += (d & 31) << sh; if (d & 32) sh += 5; else { out.push(v & 1 ? -(v >>> 1) : v >>> 1); v = 0; sh = 0; } } return out; };
function owner(src) {
  const s = src.replace(/^(\.\.\/)+/, "").replace(/^\/?/, "");
  let m = s.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/g);
  if (m) { const last = m[m.length - 1].replace("node_modules/", ""); return "npm:" + last; }
  if (/(^|\/)demo\//.test(s)) return "demo/" + (s.split(/(?:^|\/)demo\//)[1].split("/")[0]);
  if (/(^|\/)src\//.test(s)) return "src (value lib)";
  if (/(^|\/)dist\//.test(s)) return "dist (value lib build)";
  if (s.startsWith("\0") || s.includes("vite") || s.includes("rolldown")) return "bundler";
  return "other:" + s.split("/").slice(0, 2).join("/");
}
const totals = new Map(); let gzAll = 0, rawAll = 0; const chunks = [];
for (const href of hrefs) {
  const p = join(dist, href.replace(/^\.\//, ""));
  const code = readFileSync(p, "utf8"); const raw = Buffer.byteLength(code); const gz = gzipSync(readFileSync(p)).length;
  gzAll += gz; rawAll += raw; chunks.push({ href, raw, gz });
  const per = new Map();
  if (existsSync(p + ".map")) {
    const map = JSON.parse(readFileSync(p + ".map", "utf8"));
    const lines = code.split("\n"); let srcIdx = 0;
    map.mappings.split(";").forEach((line, li) => {
      const L = lines[li] ?? ""; let col = 0; const segs = [];
      for (const seg of line.split(",")) { if (!seg) continue; const d = dec(seg); col += d[0]; if (d.length >= 4) { srcIdx += d[1]; segs.push([col, srcIdx]); } else segs.push([col, -1]); }
      for (let i = 0; i < segs.length; i++) { const end = i + 1 < segs.length ? segs[i + 1][0] : L.length; const n = Buffer.byteLength(L.slice(segs[i][0], end)); const k = segs[i][1] < 0 ? "unmapped" : owner(map.sources[segs[i][1]]); per.set(k, (per.get(k) ?? 0) + n); }
    });
  } else per.set("nomap", raw);
  const mapped = [...per.values()].reduce((a, b) => a + b, 0) || 1;
  for (const [k, n] of per) { const t = totals.get(k) ?? { raw: 0, gz: 0 }; t.raw += n; t.gz += (n / mapped) * gz; totals.set(k, t); }
}
const rows = [...totals].map(([k, v]) => ({ owner: k, raw: v.raw, gz: Math.round(v.gz) })).sort((a, b) => b.gz - a.gz);
if (process.argv.includes("--json")) console.log(JSON.stringify({ dist, eagerJs: { count: chunks.length, raw: rawAll, gz: gzAll }, chunks, owners: rows }, null, 1));
else { console.log(`eager JS count=${chunks.length} raw=${rawAll} gz=${gzAll}`); for (const r of rows) console.log(`${String(r.gz).padStart(8)} gz ${String(r.raw).padStart(9)} raw  ${r.owner}`); }
